CREATE TABLE SecurityUsers(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, Username NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE, DisplayName NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
 Role NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Tenants(Id), Enabled BIGINT NOT NULL CHECK(Enabled IN(0,1)),
 Version BIGINT NOT NULL, MustChangePassword BIGINT NOT NULL CHECK(MustChangePassword IN(0,1)), PasswordHash NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
 FailedAttempts BIGINT NOT NULL DEFAULT 0, LockedUntil NVARCHAR(100) COLLATE Latin1_General_100_BIN2, CreatedAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE SecurityUserShops(UserId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SecurityUsers(Id), ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, PRIMARY KEY(UserId,ShopId));
CREATE TABLE SecurityUserWarehouses(UserId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SecurityUsers(Id), WarehouseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, PRIMARY KEY(UserId,WarehouseId));
CREATE TABLE SecuritySessions(TokenHash NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, UserId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SecurityUsers(Id), UserVersion BIGINT NOT NULL,
 ExpiresAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Revoked BIGINT NOT NULL DEFAULT 0 CHECK(Revoked IN(0,1)));
CREATE INDEX IX_SecuritySessions_User ON SecuritySessions(UserId);
CREATE TABLE SecurityOperationOwners(OperationId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, UserId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SecurityUsers(Id));
CREATE TABLE SecurityAudit(Id BIGINT IDENTITY(1,1) PRIMARY KEY, ActorId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, ActorName NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Action NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
 Resource NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, Outcome NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, OperationId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Reason NVARCHAR(500) NOT NULL);
